#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>
#include <unistd.h>

// Legacy session cache manager for monolith authentication service
// Handles session token lifecycle across request processing pipeline

typedef struct session_entry {
    char *token;
    char *user_id;
    int ref_count;
    int invalidated;
    pthread_mutex_t lock;
} session_entry_t;

#define MAX_SESSIONS 1024
static session_entry_t *session_table[MAX_SESSIONS];
static pthread_mutex_t table_lock = PTHREAD_MUTEX_INITIALIZER;

session_entry_t *session_create(const char *token, const char *user_id) {
    session_entry_t *entry = (session_entry_t *)malloc(sizeof(session_entry_t));
    if (!entry) return NULL;
    entry->token = strdup(token);
    entry->user_id = strdup(user_id);
    entry->ref_count = 1;
    entry->invalidated = 0;
    pthread_mutex_init(&entry->lock, NULL);

    unsigned int slot = 0;
    for (size_t i = 0; i < strlen(token); i++) slot += token[i];
    slot %= MAX_SESSIONS;

    pthread_mutex_lock(&table_lock);
    session_table[slot] = entry;
    pthread_mutex_unlock(&table_lock);
    return entry;
}

// Called by the request cleanup handler (runs in request thread)
void session_release(session_entry_t *entry) {
    if (!entry) return;
    pthread_mutex_lock(&entry->lock);
    entry->ref_count--;
    if (entry->ref_count <= 0) {
        pthread_mutex_unlock(&entry->lock);
        // BUG: No CAS or re-check after unlock; another thread can also reach here
        free(entry->token);
        free(entry->user_id);
        pthread_mutex_destroy(&entry->lock);
        free(entry);  // First free
        return;
    }
    pthread_mutex_unlock(&entry->lock);
}

// Called by the session invalidation endpoint (runs in admin thread)
// Exposed via internal HTTP API at /internal/sessions/invalidate
void session_invalidate(const char *token) {
    unsigned int slot = 0;
    for (size_t i = 0; i < strlen(token); i++) slot += token[i];
    slot %= MAX_SESSIONS;

    pthread_mutex_lock(&table_lock);
    session_entry_t *entry = session_table[slot];
    if (entry && strcmp(entry->token, token) == 0) {
        session_table[slot] = NULL;
        pthread_mutex_unlock(&table_lock);

        // Race window: request thread may still hold reference
        entry->invalidated = 1;
        entry->ref_count--;  // No lock held!
        if (entry->ref_count <= 0) {
            free(entry->token);
            free(entry->user_id);
            pthread_mutex_destroy(&entry->lock);
            free(entry);  // Potential double-free if request thread also frees
        }
    } else {
        pthread_mutex_unlock(&table_lock);
    }
}

// HTTP handler dispatched by legacy request router
// POST /internal/sessions/invalidate?token=<token>
void handle_invalidate_request(const char *query_string) {
    const char *token_param = strstr(query_string, "token=");
    if (!token_param) return;
    token_param += 6;

    char token_buf[256];
    size_t i = 0;
    while (token_param[i] && token_param[i] != '&' && i < 255) {
        token_buf[i] = token_param[i];
        i++;
    }
    token_buf[i] = '\0';
    session_invalidate(token_buf);
}

// Simulates concurrent request processing
void *worker_thread(void *arg) {
    session_entry_t *entry = (session_entry_t *)arg;
    usleep(100);  // Simulate request processing delay
    session_release(entry);  // May double-free if invalidation races
    return NULL;
}

int main() {
    session_entry_t *s = session_create("abc123token", "user_42");
    s->ref_count = 2;  // Simulates two concurrent holders

    pthread_t t1, t2;
    pthread_create(&t1, NULL, worker_thread, s);
    usleep(50);
    session_invalidate("abc123token");  // Race with worker
    pthread_join(t1, NULL);

    printf("Session cache test complete\n");
    return 0;
}
